def brokenKeyboard(keys):
    front = []
    back = []
    run = []
    home = False
    for ch in keys + '[':
        if ch == '[' or ch == ']':
            block = "".join(run)
            run = []
            if home:
                front.append(block)
            else:
                back.append(block)
            home = (ch == '[')
        else:
            run.append(ch)
    # the sentinel '[' above only flushes the last block
    return "".join(reversed(front)) + "".join(back)
